#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    int minOperationsToSort(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;
        bool isFwd = true, isBwd = true;
        for (int i = 0; i < n; ++i) {
            if (nums[i] != (nums[0] + i) % n) isFwd = false;
            if (nums[i] != (nums[0] - i + n) % n) isBwd = false;
        }
        if (!isFwd && !isBwd) return -1;
        int pos0 = std::find(nums.begin(), nums.end(), 0) - nums.begin();
        int startRev = (isBwd && !isFwd) ? 1 : 0;

        std::vector<std::vector<int>> dist(n, std::vector<int>(2, -1));
        std::queue<std::pair<int, int>> q;
        q.push({pos0, startRev});
        dist[pos0][startRev] = 0;
        while (!q.empty()) {
            auto [p, rev] = q.front();
            q.pop();
            int d = dist[p][rev];
            if (p == 0 && rev == 0) return d;
            int nxtP1 = n - 1 - p, nxtRev1 = 1 - rev;
            if (dist[nxtP1][nxtRev1] == -1) {
                dist[nxtP1][nxtRev1] = d + 1;
                q.push({nxtP1, nxtRev1});
            }
            int nxtP2 = (p - 1 + n) % n, nxtRev2 = rev;
            if (dist[nxtP2][nxtRev2] == -1) {
                dist[nxtP2][nxtRev2] = d + 1;
                q.push({nxtP2, nxtRev2});
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minOperationsToSort(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;
        boolean isFwd = true, isBwd = true;
        for (int i = 0; i < n; i++) {
            if (nums[i] != (nums[0] + i) % n) isFwd = false;
            if (nums[i] != (nums[0] - i + n) % n) isBwd = false;
        }
        if (!isFwd && !isBwd) return -1;
        int pos0 = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) { pos0 = i; break; }
        }
        int startRev = (isBwd && !isFwd) ? 1 : 0;
        int[][] dist = new int[n][2];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{pos0, startRev});
        dist[pos0][startRev] = 0;
        while (!q.isEmpty()) {
            int[] top = q.poll();
            int p = top[0], rev = top[1];
            int d = dist[p][rev];
            if (p == 0 && rev == 0) return d;
            int np1 = n - 1 - p, nr1 = 1 - rev;
            if (dist[np1][nr1] == -1) {
                dist[np1][nr1] = d + 1;
                q.offer(new int[]{np1, nr1});
            }
            int np2 = (p - 1 + n) % n, nr2 = rev;
            if (dist[np2][nr2] == -1) {
                dist[np2][nr2] = d + 1;
                q.offer(new int[]{np2, nr2});
            }
        }
        return -1;
    }
}

